/* jshint esversion: 8 */
const filename = 'twitter_{user-name}(@{user-id})_{date-time}_{status-id}_{file-type}'
const TMD = (function () {
    let lang, host, history, show_sensitive, is_tweetdeck, eagle_root_segments, eagle_child_template
    return {
        /**
         * 统一解析当前界面应使用的语言。
         *
         * 旧逻辑只看 <html lang>：
         * - 但 X 页面经常仍然返回 en
         * - 即使用户浏览器、系统、Tampermonkey 都是中文，按钮仍会显示英文
         *
         * 这里改为：
         * 1. 优先读取页面 lang
         * 2. 再读取浏览器语言 navigator.language / navigator.languages
         * 3. 将 zh-CN / zh-SG / zh-MY 归一为 zh
         * 4. 将 zh-TW / zh-HK / zh-MO 归一为 zh-Hant
         * 5. 如果都识别不到，再回退英文
         */
        resolveLanguage: function () {
            const candidates = [
                document.querySelector('html')?.lang || '',
                navigator.language || '',
                ...(Array.isArray(navigator.languages) ? navigator.languages : []),
            ]
                .map(v => String(v || '').trim())
                .filter(Boolean)

            // 第一轮：优先命中中文变体，避免 html lang= en 抢先把界面固定成英文。
            for (const raw of candidates) {
                const code = raw.toLowerCase()
                if (code.startsWith('zh-cn') || code.startsWith('zh-sg') || code.startsWith('zh-my') || code === 'zh') {
                    return this.language.zh
                }
                if (code.startsWith('zh-tw') || code.startsWith('zh-hk') || code.startsWith('zh-mo') || code.startsWith('zh-hant')) {
                    return this.language['zh-Hant']
                }
            }

            // 第二轮：再处理其他语言的精确匹配。
            for (const raw of candidates) {
                const code = raw.toLowerCase()
                if (this.language[raw]) return this.language[raw]
                if (this.language[code]) return this.language[code]
            }

            return this.language.en
        },
        /**
         * 把用户填写的 Eagle 根目录文本解析成稳定的目录数组。
         *
         * 输入示例：
         * - "X"
         * - "社媒采集/X"
         * - "社媒采集\\X"
         *
         * 输出示例：
         * - ["X"]
         * - ["社媒采集", "X"]
         */
        parseEagleRootPath: function (rawValue) {
            const parts = String(rawValue || 'X')
                .split(/[\\/]+/g)
                .map(part => this.sanitizeFolderSegment(part))
                .filter(Boolean)

            return parts.length > 0 ? parts : ['X']
        },
        /**
         * 供设置面板 / 导入逻辑共用的根目录展示文本。
         */
        getEagleRootPathText: function () {
            const parts = Array.isArray(eagle_root_segments) && eagle_root_segments.length > 0
                ? eagle_root_segments
                : ['X']
            return parts.join('/')
        },
        /**
         * 解析“自动子目录模板”。
         *
         * 默认值：
         * - {page-scope}/{page-type}
         *
         * 可用占位符：
         * - {page-scope} 当前页面主体，例如 Laobai_Art / 书签 / 首页时间线
         * - {page-type} 当前页面类别，例如 喜欢 / 媒体 / 主页 / 单条推文
         * - {page-owner} 当前页面归属用户，例如 NASA / Laobai_Art
         * - {author} 当前资源作者（推文作者）
         */
        parseEagleChildTemplate: function (rawValue) {
            const template = String(rawValue || '{page-scope}/{page-type}')
                .trim()
                .replace(/\\/g, '/')
            return template || '{page-scope}/{page-type}'
        },
        /**
         * 供设置面板展示当前子目录模板。
         */
        getEagleChildTemplateText: function () {
            return this.parseEagleChildTemplate(eagle_child_template || '{page-scope}/{page-type}')
        },
        init: async function () {
            const menuLang = this.resolveLanguage()
            GM_registerMenuCommand(menuLang.settings, this.settings)
            GM_registerMenuCommand(menuLang.export_history || 'Export History (Markdown)', async () => this.exportHistory())
            lang = this.resolveLanguage()
            /**
             * 读取 Eagle 根目录配置。
             *
             * 例如用户填写：
             * - X
             * - 社媒采集/X
             * - 灵感库/X
             *
             * 最终都会被解析成目录数组，后续拼接到站点上下文目录前面。
             */
            eagle_root_segments = this.parseEagleRootPath(await GM_getValue('eagle_root_path', 'X'))
            /**
             * 读取“自动子目录模板”配置。
             * 目录模板单独拆出来后，用户就能保留一个固定父目录，
             * 同时灵活定义后续层级规则。
             */
            eagle_child_template = this.parseEagleChildTemplate(await GM_getValue('eagle_child_template', '{page-scope}/{page-type}'))
            window.__TMD_LANG_DEBUG = {
                htmlLang: document.querySelector('html')?.lang || '',
                navigatorLanguage: navigator.language || '',
                resolvedDownloadText: lang && lang.download,
                resolvedSettingsText: lang && lang.settings,
            }
            /**
             * 暴露一个只读调试入口，便于后续排查用户环境问题。
             * 这不会影响普通用户使用，但在后台自动化测试里很有帮助。
             */
            window.__TMD_DEBUG__ = this
            host = location.hostname
            is_tweetdeck = host.indexOf('tweetdeck') >= 0
            history = this.storage_obsolete()
            if (history.length) {
                this.storage(history)
                this.storage_obsolete(true)
            } else history = await this.storage()
            /**
             * 这里必须 await：
             * GM_getValue 在新版 Tampermonkey 中可能返回 Promise。
             * 如果不等待，show_sensitive 会变成 Promise 对象，
             * 后续 if (show_sensitive) 判断会始终为真，带来一堆误判。
             */
            show_sensitive = await GM_getValue('show_sensitive', false)
            document.head.insertAdjacentHTML('beforeend', '<style>' + this.css + (show_sensitive ? this.css_ss : '') + '</style>')
            let observer = new MutationObserver(ms => ms.forEach(m => m.addedNodes.forEach(node => this.detect(node))))
            observer.observe(document.body, { childList: true, subtree: true })

            /**
             * 关键修复 1：
             * 原脚本只监听“后续新增节点”，没有扫描“页面初始已存在的推文内容”。
             * 在 X 这种 SPA 页面里，这会直接导致页面已经渲染完成时完全不显示下载按钮。
             *
             * 因此这里补 3 层兜底：
             * 1. 初始化立即全页扫描
             * 2. 延迟再次扫描，兼容页面分阶段渲染
             * 3. 定时轻量重扫，兼容 X 的无刷新路由切换 / 懒加载
             */
            this.scanExisting(document)
            setTimeout(() => this.scanExisting(document), 1200)
            setTimeout(() => this.scanExisting(document), 3000)
            setInterval(() => this.scanExisting(document), 2500)
            this.ensureBatchPanel()
        },
        exportHistory: async function () {
            try {
                const history = await GM_getValue('download_history', [])
                if (!history || !Array.isArray(history) || history.length === 0) {
                    return
                }
                const markdownContent = '# Twitter/X Media Downloader history\n\n' +
                    (await Promise.all(history.map(id => this.generateMarkdown(id)))).join('\n')
                const blob = new Blob([markdownContent], { type: 'text/markdown;charset=utf-8' })
                const link = document.createElement('a')
                link.href = URL.createObjectURL(blob)
                link.download = `twitter_download_history_(${history.length}).md`
                document.body.appendChild(link)
                link.click()
                document.body.removeChild(link)
                URL.revokeObjectURL(link.href)
            } catch (error) {
                console.error('An error occurred while exporting Markdown history:', error)
                alert('An error occurred while exporting Markdown history, please check the console for details.')
            }
        },
        generateMarkdown: async function (tweet_id, fetch = true) {
            if (!fetch) return `[Tweet] - ${tweet_id} (https://x.com/i/web/status/${tweet_id})`
            let json = await this.fetchJson(tweet_id)
            let tweet = json.quoted_status_result?.result?.legacy?.media
                || json.quoted_status_result?.result?.legacy
                || json.legacy
            let user = json.core.user_results.result.legacy
            let user_name = user.name.replace(/([\\/|*?:"\u200b-\u200d\u2060\ufeff]|🔞)/g, v => invalid_chars[v])
            let full_text = tweet.full_text.split('\n').join(' ').replace(/\s*https:\/\/t\.co\/\w+/g, '').replace(/[\\/|<>*?:"\u200b-\u200d\u2060\ufeff]/g, v => invalid_chars[v])
            return `[${user_name} (@${user.screen_name})](https://x.com/i/web/status/${tweet_id})\n>  ${full_text}\n`
        },
        detect: function (node) {
            let article = node.tagName == 'ARTICLE' && node || node.tagName == 'DIV' && (node.querySelector('article') || node.closest('article'))
            if (article) this.addButtonTo(article)
            let listitems = node.tagName == 'LI' && node.getAttribute('role') == 'listitem' && [node] || node.tagName == 'DIV' && node.querySelectorAll('li[role="listitem"]')
            if (listitems) this.addButtonToMedia(listitems)
        },
        /**
         * 主动扫描当前页面中已经存在的推文与媒体列表项。
         * 这是给 X/Twitter 单页应用补上的“首屏扫描 + 路由切换重扫”能力。
         */
        scanExisting: function (root) {
            let scope = root || document
            scope.querySelectorAll && scope.querySelectorAll('article').forEach(article => this.addButtonTo(article))
            scope.querySelectorAll && scope.querySelectorAll('li[role="listitem"]').forEach(li => this.addButtonToMedia([li]))
        },
        /**
         * 从推文节点中安全提取 status id。
         * X 页面结构经常变化，不能再直接假设 querySelector 一定有值。
         */
        getStatusId: function (root, fallback) {
            if (fallback) return fallback
            let link = root && root.querySelector && root.querySelector('a[href*="/status/"]')
            if (!link || !link.href) return ''
            let match = link.href.match(/\/status\/(\d+)/)
            return match ? match[1] : ''
        },
        /**
         * 找到操作按钮组。
         * 旧脚本只用 last-of-type，过于依赖结构顺序；这里做多一层兼容。
         */
        getActionGroup: function (article) {
            return article.querySelector('div[role="group"]:last-of-type, div[role="group"], ul.tweet-actions, ul.tweet-detail-actions')
        },
        /**
         * 找到“分享按钮”的外层容器，用于 clone 出下载按钮。
         * 若匹配不到，则返回按钮组最后一个子项作为兜底。
         */
        getShareItem: function (btn_group) {
            if (!btn_group) return null
            let candidates = Array.from(btn_group.querySelectorAll(':scope>div>div, li.tweet-action-item>a, li.tweet-detail-action-item>a'))
            let last = candidates.pop()
            if (last && last.parentNode) return last.parentNode
            return btn_group.lastElementChild || null
        },
        addButtonTo: function (article) {
            if (!article) return
            let media_selector = [
                'a[href*="/photo/1"]',
                'div[role="progressbar"]',
                'button[data-testid="playButton"]',
                'a[href="/settings/content_you_see"]', //hidden content
                'div.media-image-container', // for tweetdeck
                'div.media-preview-container', // for tweetdeck
                'div[aria-labelledby]>div:first-child>div[role="button"][tabindex="0"]' //for audio (experimental)
            ]
            let media = article.querySelector(media_selector.join(','))
            let current_tweet_id = document.location.href.includes('/status/') 
                ? document.location.href.split('/status/').pop().split('/').shift() 
                : undefined
            if (media) {
                if (article.querySelector('.tmd-down:not(.tmd-img):not(.tmd-media)')) return
                let status_id = this.getStatusId(article, current_tweet_id)
                if (!status_id) return
                let btn_group = this.getActionGroup(article)
                let btn_share = this.getShareItem(btn_group)
                if (!btn_group || !btn_share) return
                let btn_down = btn_share.cloneNode(true)
                let button = btn_down.querySelector('button')
                if (button) button.removeAttribute('disabled')
                if (is_tweetdeck) {
                    btn_down.firstElementChild.innerHTML = '<svg viewBox="0 0 24 24" style="width: 18px; height: 18px;">' + this.svg + '</svg>'
                    btn_down.firstElementChild.removeAttribute('rel')
                    btn_down.classList.replace('pull-left', 'pull-right')
                } else {
                    let svg = btn_down.querySelector('svg')
                    if (!svg) return
                    svg.innerHTML = this.svg
                }
                let is_exist = history.indexOf(status_id) >= 0
                this.status(btn_down, 'tmd-down')
                this.status(btn_down, is_exist ? 'completed' : 'download', is_exist ? lang.completed : lang.download)
                btn_group.insertBefore(btn_down, btn_share.nextSibling)
                btn_down.onclick = () => this.click(btn_down, status_id, is_exist)
                this.addEagleButtonToActionGroup(btn_group, btn_share, status_id)
                if (show_sensitive) {
                    let btn_show = article.querySelector('div[aria-labelledby] div[role="button"][tabindex="0"]:not([data-testid]) > div[dir] > span > span')
                    if (btn_show) btn_show.click()
                }
            }
            let imgs = article.querySelectorAll('a[href*="/photo/"]')
            if (imgs.length > 1) {
                let status_id = this.getStatusId(article, current_tweet_id)
                if (!status_id) return
                imgs.forEach(img => {
                    if (!img.parentNode || img.parentNode.querySelector('.tmd-down.tmd-img')) return
                    let index = img.href.split('/status/').pop().split('/').pop()
                    let is_exist = history.indexOf(status_id) >= 0
                    let btn_down = document.createElement('div')
                    btn_down.innerHTML = '<div><div><svg viewBox="0 0 24 24" style="width: 18px; height: 18px;">' + this.svg + '</svg></div></div>'
                    btn_down.classList.add('tmd-down', 'tmd-img')
                    this.status(btn_down, 'download')
                    img.parentNode.appendChild(btn_down)
                    btn_down.onclick = e => {
                        e.preventDefault()
                        this.click(btn_down, status_id, is_exist, index)
                    }
                })
            }
        },
        addButtonToMedia: function (listitems) {
            listitems.forEach(li => {
                if (!li || li.querySelector(':scope > .tmd-down.tmd-media')) return
                let status_id = this.getStatusId(li)
                if (!status_id) return
                let is_exist = history.indexOf(status_id) >= 0
                let btn_down = document.createElement('div')
                btn_down.innerHTML = '<div><div><svg viewBox="0 0 24 24" style="width: 18px; height: 18px;">' + this.svg + '</svg></div></div>'
                btn_down.classList.add('tmd-down', 'tmd-media')
                this.status(btn_down, is_exist ? 'completed' : 'download', is_exist ? lang.completed : lang.download)
                li.appendChild(btn_down)
                btn_down.onclick = () => this.click(btn_down, status_id, is_exist)
            })
        },
        selectTweetDialog: function (originalUser, quotedUser) {
            return new Promise((resolve) => {
                // 创建遮罩层
                const overlay = document.createElement('div')
                overlay.style.cssText = `
                    position: fixed;
                    left: 0;
                    top: 0;
                    width: 100%;
                    height: 100%;
                    background-color: rgba(0, 0, 0, 0.7);
                    z-index: 10000;
                    display: flex;
                    justify-content: center;
                    align-items: center;
                `

                // 创建对话框
                const dialog = document.createElement('div')
                dialog.style.cssText = `
                    background: white;
                    border-radius: 16px;
                    padding: 24px;
                    width: 400px;
                    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
                    font-family: system-ui, -apple-system, sans-serif;
                `

                // 添加标题
                const title = document.createElement('h3')
                title.textContent = `${lang.choose}`
                title.style.cssText = `
                    margin-top: 0;
                    margin-bottom: 20px;
                    text-align: center;
                    color: #0f1419;
                `

                // 添加选项按钮容器
                const buttonsContainer = document.createElement('div')
                buttonsContainer.style.cssText = `
                    display: flex;
                    flex-direction: column;
                    gap: 12px;
