                    const ok = await this.ensurePermission(handle)
                    if (!ok) throw new Error('FOLDER_PICK_CANCELLED')
                    this.dirHandle = handle
                    return handle
                } catch (err) {
                    if (err && (err.name === 'AbortError' || String(err.message || err).includes('aborted'))) {
