         */
        resolveTweetSource: async function (json, status_id, options = {}) {
            const originalTweet = json?.legacy
            const originalUser = json?.core?.user_results?.result?.legacy
            const quotedResult = json?.quoted_status_result?.result
            const quotedTweet = quotedResult?.legacy
            const quotedUser = quotedResult?.core?.user_results?.result?.legacy

            const originalHasMedia = this.hasDownloadableMedia(originalTweet)
            const quotedHasMedia = this.hasDownloadableMedia(quotedTweet)

            let choice = 'original'

            if (options.preferredChoice === 'quoted' && quotedHasMedia) {
                choice = 'quoted'
            } else if (options.preferredChoice === 'original' && originalHasMedia) {
