        prepareMediaPayload: async function (status_id, options = {}) {
            const out = (await GM_getValue('filename', filename)).split('\n').join('')
            const json = options.json || await this.fetchJson(status_id)
            const resolved = await this.resolveTweetSource(json, status_id, options)
            if (!resolved) return null

            const tweet = resolved.tweet
            const user = resolved.user
            const invalid_chars = this.invalidChars()

            if (json?.card && !this.hasDownloadableMedia(tweet)) {
                throw new Error('This tweet contains a link, which is not supported by this script.')
            }
            if (!tweet || !user) {
