            }

            let medias = this.extractTweetMedia(tweet)
            if (!Array.isArray(medias) || medias.length === 0) {
                throw new Error('MEDIA_NOT_FOUND')
            }
            if (options.index) medias = [medias[options.index - 1]].filter(Boolean)

            const datetime = out.match(/\{date-time(-local)?:[^{}]+\}/)
                ? out.match(/\{date-time(?:-local)?:([^{}]+)\}/)[1].replace(/[\\/|<>*?:"]/g, v => invalid_chars[v])
                : 'YYYYMMDD-hhmmss'

            const info = {}
            info['status-id'] = resolved.statusId
            info['user-name'] = user.name.replace(/([\\/|*?:"\u200b-\u200d\u2060\ufeff]|🔞)/g, v => invalid_chars[v])
            info['user-id'] = user.screen_name
            info['date-time'] = this.formatDate(tweet.created_at, datetime)
            info['date-time-local'] = this.formatDate(tweet.created_at, datetime, true)
            info['full-text'] = (tweet.full_text || '')
                .split('\n')
                .join(' ')
                .replace(/\s*https:\/\/t\.co\/\w+/g, '')
                .replace(/[\\/|<>*?:"\u200b-\u200d\u2060\ufeff]/g, v => invalid_chars[v])

            const tweetUrl = `https://${host}/${user.screen_name}/status/${resolved.statusId}`
            /**
             * 根据当前浏览页面，推导“这次保存动作来自哪里”。
             *
             * 这里的语义非常重要：
             * 1. 推文作者（user-id）描述的是“资源是谁发的”；
             * 2. 页面上下文（likes / media / bookmarks）描述的是“我是从哪个列表里采集的”。
