                        .filter(n => n.content_type == 'video/mp4')
                        .sort((a, b) => (b.bitrate || 0) - (a.bitrate || 0))[0].url
                /**
                 * 为每个媒体生成稳定指纹：
                 * - 优先使用 X 返回的媒体唯一 id / media_key
                 * - 如果拿不到，再退回到归一化后的原始媒体 url
                 *
                 * 这样即使你后续改了文件命名规则，
                 * 已导入过的媒体仍然可以被正确识别并跳过。
                 */
                const stableMediaId = String(media?.id_str || media?.media_key || media?.id || '').trim()
                const normalizedMediaUrl = String(
                    media.type == 'photo'
                        ? (media.media_url_https || '')
                        : (
                            media.video_info.variants
                                .filter(n => n.content_type == 'video/mp4')
                                .sort((a, b) => (b.bitrate || 0) - (a.bitrate || 0))[0].url || ''
                        )
                )
                    .replace(/:orig$/i, '')
                    .replace(/[?#].*$/, '')
                const mediaFingerprint = [
                    String(resolved.statusId || '').trim(),
                    stableMediaId || normalizedMediaUrl,
                    String(media.type || '').trim(),
                ].filter(Boolean).join('::')
                info.file = info.url.split('/').pop().split(/[:?]/).shift()
                info['file-name'] = info.file.split('.').shift()
                info['file-ext'] = info.file.split('.').pop()
                info['file-type'] = media.type.replace('animated_', '')
                info.out = (out.replace(/\.?\{file-ext\}/, '') + ((medias.length > 1 || options.index) && !out.match('{file-name}') ? '-' + (options.index ? options.index - 1 : i) : '') + '.{file-ext}')
                    .replace(/\{([^{}:]+)(:[^{}]+)?\}/g, (match, name) => info[name])

                const mediaIndex = options.index ? options.index - 1 : i
                // buildEagleDedupeTag ?? Eagle ???????? this.buildEagleDedupeTag?
                // ????????? prepareMediaPayload ???????
                // ?????????? Eagle ???? media=0??? fail?
                const dedupeTag = this.eagle.buildEagleDedupeTag({
                    statusId: resolved.statusId,
