         * 作者信息继续保留在标签里，后续搜索时不会丢。
         */
        getCurrentPageContext: function (fallbackHandle = '') {
            const pathname = String(location.pathname || '/')
            const parts = pathname.split('/').filter(Boolean)
            const reserved = new Set([
                'home', 'explore', 'search', 'notifications', 'messages', 'i', 'settings',
                'compose', 'jobs', 'communities', 'lists', 'topics', 'privacy', 'tos',
                'login', 'signup', 'intent', 'share', 'download'
            ])
            const isHandle = (value) => {
                const v = String(value || '').trim().replace(/^@/, '')
                return !!v && !reserved.has(v.toLowerCase())
            }

            let ownerHandle = ''
            let pageType = 'timeline'
            let folderScope = ''
            let folderLabel = ''
            let tagLabel = '时间线'

            if (parts[0] === 'i' && parts[1] === 'bookmarks') {
                pageType = 'bookmarks'
                folderScope = '书签'
                tagLabel = '书签'
            } else if (parts[0] === 'home') {
                pageType = 'home'
                folderScope = '首页时间线'
                tagLabel = '首页'
            } else if (parts[0] === 'notifications') {
                pageType = 'notifications'
                folderScope = '通知'
                tagLabel = '通知'
            } else if (parts[0] === 'search') {
                pageType = 'search'
                folderScope = '搜索'
                tagLabel = '搜索'
            } else if (parts.length >= 2 && isHandle(parts[0]) && parts[1] === 'likes') {
                ownerHandle = parts[0]
                pageType = 'likes'
                folderScope = ownerHandle
                folderLabel = '喜欢'
                tagLabel = '喜欢'
