                ownerHandle = parts[0]
                pageType = 'media'
                folderScope = ownerHandle
                folderLabel = '媒体'
                tagLabel = '媒体'
            } else if (parts.length >= 2 && isHandle(parts[0]) && parts[1] === 'with_replies') {
                ownerHandle = parts[0]
                pageType = 'with_replies'
                folderScope = ownerHandle
                folderLabel = '回复'
                tagLabel = '回复'
            } else if (parts.length >= 2 && isHandle(parts[0]) && parts[1] === 'status') {
                ownerHandle = parts[0]
                pageType = 'status'
                folderScope = ownerHandle
                folderLabel = '单条推文'
                tagLabel = '单条推文'
            } else if (parts.length >= 1 && isHandle(parts[0])) {
