        buildEagleFolderPath: function (pageContext, fallbackHandle = '') {
            /**
             * 目录结构规则：
             * 1. 先使用用户可配置的 Eagle 根目录
             * 2. 再拼接当前页面归档层级
             *
             * 例如：
             * - 根目录 = X
             *   => X / Laobai_Art / 喜欢
             * - 根目录 = 社媒采集/X
             *   => 社媒采集 / X / Laobai_Art / 喜欢
             */
            const segments = Array.isArray(eagle_root_segments) && eagle_root_segments.length > 0
                ? [...eagle_root_segments]
                : ['X']
            const dynamicSegments = this.resolveEagleChildTemplateSegments(pageContext, fallbackHandle)
            if (dynamicSegments.length === 0) {
                const scope = this.sanitizeFolderSegment(pageContext?.folderScope || fallbackHandle || '时间线')
                const leaf = this.sanitizeFolderSegment(pageContext?.folderLabel || '')
                if (scope) segments.push(scope)
