                const eagleBtn = this.panel.querySelector('[data-action="eagle"]')
                const stopBtn = this.panel.querySelector('[data-action="stop"]')
                downloadBtn.disabled = this.running
                eagleBtn.disabled = this.running
                stopBtn.disabled = !this.running
                this.panel.classList.toggle('running', this.running)
            },
            getTimelineStatusIds: function (ctx) {
                const ids = []
                const seen = new Set()
                document.querySelectorAll('article').forEach(article => {
                    const media_selector = [
                        'a[href*="/photo/1"]',
                        'a[href*="/photo/"]',
                        'video',
                        'div[role="progressbar"]',
                        'button[data-testid="playButton"]',
                        'div[aria-labelledby]>div:first-child>div[role="button"][tabindex="0"]'
                    ]
                    const hasMedia = article.querySelector(media_selector.join(',')) || article.querySelectorAll('a[href*="/photo/"]').length > 0
                    if (!hasMedia) return
                    const statusId = ctx.getStatusId(article)
                    if (!statusId || seen.has(statusId)) return
                    seen.add(statusId)
                    ids.push(statusId)
                })
                return ids
            },
            /**
             * X ???? / ??? / ?????????????
             * ???? smooth scroll?????????????????
             * ?????????????????????????
             */
            scrollForMore: async function (ctx) {
                const scroller = document.scrollingElement || document.documentElement || document.body
                const before = {
                    top: scroller ? scroller.scrollTop : window.scrollY,
                    height: scroller ? scroller.scrollHeight : document.body.scrollHeight,
                    articleCount: document.querySelectorAll('article').length,
                }

                /**
                 * X ???????????????????? DOM ????
                 * ??????????????????????????
                 */
                const step = Math.max(Math.floor(window.innerHeight * 0.85), 720)
                for (let i = 0; i < 5; i++) {
                    const currentScroller = document.scrollingElement || document.documentElement || document.body
                    const currentTop = currentScroller ? currentScroller.scrollTop : window.scrollY
                    window.scrollTo({ top: currentTop + step, behavior: 'auto' })
                    await ctx.sleep(900)
                    ctx.scanExisting(document)
                }

                await ctx.sleep(1800)
                ctx.scanExisting(document)

                const afterScroller = document.scrollingElement || document.documentElement || document.body
                const after = {
                    top: afterScroller ? afterScroller.scrollTop : window.scrollY,
                    height: afterScroller ? afterScroller.scrollHeight : document.body.scrollHeight,
                    articleCount: document.querySelectorAll('article').length,
                }

                return {
                    before,
                    after,
                    changed: after.height > before.height || after.articleCount > before.articleCount || after.top > before.top + 80,
                }
            },
            async start(ctx, mode) {
                if (this.running) return
                let localDirHandle = null
                let useLocalDirectoryWriter = false
                if (mode === 'eagle') {
                    try {
                        await ctx.eagle.checkAlive()
                    } catch (err) {
                        this.setText(lang.eagle_unavailable, err.message)
                        return
                    }
                }
                if (mode === 'download' && ctx.localDownload.isSupported()) {
                    try {
                        this.setText(lang.batch_download_running, lang.batch_pick_folder || '?????????????')
                        localDirHandle = await ctx.localDownload.ensureDirectory(false)
                        useLocalDirectoryWriter = !!localDirHandle
                    } catch (err) {
                        if (String(err.message || err) === 'FOLDER_PICK_CANCELLED') {
                            this.setText(lang.batch_stopped, lang.batch_folder_cancelled || '????????')
                            return
                        }
                        this.setText(lang.batch_stopped, err.message || String(err))
                        return
                    }
                }

                this.running = true
                this.mode = mode
                this.processed = new Set()
                this.successTweets = 0
                this.failedTweets = 0
                this.successMedia = 0
                this.skippedMedia = 0
                this.failedMedia = 0
                this.lastError = ''
                this.renderButtons()
                this.setText(
                    mode === 'download' ? lang.batch_download_running : lang.batch_eagle_running,
                    mode === 'download' && useLocalDirectoryWriter ? (lang.batch_writing_local || '????????????????...') : lang.batch_scanning
                )

                let idleRounds = 0
                let lastScrollTop = -1
                // Eagle ???????????????????????????????
                // ????????? 30 ??????????????
                const continuousMode = mode === 'eagle'

                while (this.running && (continuousMode || idleRounds < 30)) {
                    /**
                     * ????????? DOM???????????????/?????????????????
                     * ??????????????????????????????????
                     */
                    ctx.scanExisting(document)

                    const ids = this.getTimelineStatusIds(ctx)
                    const pending = ids.filter(id => !this.processed.has(id))

                    if (pending.length === 0) {
                        const scrollResult = await this.scrollForMore(ctx)
                        if (scrollResult.changed) {
                            idleRounds = 0
                        } else {
                            idleRounds++
                        }
                        this.setText(
                            mode === 'download' ? lang.batch_download_running : lang.batch_eagle_running,
                            this.formatProgress(
                                continuousMode
                                    ? `${lang.batch_scrolling}\uff08\u6301\u7eed\u6a21\u5f0f\uff0c\u7a7a\u8f6c ${idleRounds} \u8f6e\uff0c\u70b9\u505c\u6b62\u7ed3\u675f\uff09`
                                    : `${lang.batch_scrolling}\uff08${idleRounds}/30\uff09`
                            )
                        )
                        lastScrollTop = scrollResult.after.top
                        continue
                    }

                    idleRounds = 0

                    for (const id of pending) {
                        if (!this.running) break
                        this.processed.add(id)
                        this.setText(
                            mode === 'download' ? lang.batch_download_running : lang.batch_eagle_running,
                            `${lang.batch_processing} ${this.processed.size}`
                        )

                        let payload = null
                        try {
                            payload = await ctx.prepareMediaPayload(id, {
                                promptIfQuoted: false,
                                preferredChoice: 'original',
                            })

                            if (!payload || !payload.tasks || payload.tasks.length === 0) {
                                throw new Error('MEDIA_NOT_FOUND')
                            }

                            if (mode === 'download') {
                                for (const task of payload.tasks) {
                                    if (useLocalDirectoryWriter && localDirHandle) {
                                        await ctx.localDownload.saveTask(task, localDirHandle)
                                    } else {
                                        await ctx.downloader.downloadViaBrowser(task)
                                    }
                                    this.successMedia++
                                    await ctx.sleep(250)
                                }
                            } else {
                                const eagleResult = await ctx.eagle.addItemsByUrl(payload.tasks)
                                const savedCount = Number(eagleResult?.savedCount || 0)
                                const skippedCount = Number(eagleResult?.skippedCount || 0)
                                this.successMedia += savedCount
                                this.skippedMedia += skippedCount
                                this.setText(
                                    lang.batch_eagle_running,
                                    savedCount > 0
                                        ? `${lang.batch_processing} ${this.processed.size}\uff5c\u65b0\u589e ${savedCount}\uff5c\u8df3\u8fc7 ${skippedCount}`
                                        : `${lang.batch_processing} ${this.processed.size}\uff5c\u672c\u8f6e\u672a\u65b0\u589e\uff5c\u8df3\u8fc7 ${skippedCount}`
                                )
                                await ctx.sleep(220)
                            }

                            this.successTweets++
                        } catch (err) {
                            const failedCount = payload && Array.isArray(payload.tasks) && payload.tasks.length > 0 ? payload.tasks.length : 1
                            this.failedTweets++
                            this.failedMedia += failedCount

                            /**
                             * ????????????
                             * ???????? fail ????????? X ?????????????? Eagle ?????
                             * ??????????????????????????????
                             */
                            const errText = String(err?.message || err || 'UNKNOWN_ERROR').slice(0, 160)
                            this.lastError = errText
                            console.error('[TMD][batch]', mode, id, err)
                            this.setText(
                                mode === 'download' ? lang.batch_download_running : lang.batch_eagle_running,
                                `\u5931\u8d25 ${this.failedTweets}\uff1a${errText}`
                            )
                        }

                        this.setText(
                            mode === 'download' ? lang.batch_download_running : lang.batch_eagle_running,
                            this.formatProgress(this.lastError ? '\u6700\u8fd1\u9519\u8bef\uff1a' + this.lastError : '')
                        )
                        await ctx.sleep(500)
                    }
                }

                const finishedByUser = !this.running
                this.running = false
                this.renderButtons()
                this.setText(
                    finishedByUser ? lang.batch_stopped : lang.batch_done,
                    this.formatProgress()
                )
            },
            stop: function () {
                this.running = false
                this.setText(lang.batch_stopped, this.formatProgress())
                this.renderButtons()
            }
        },
        /**
         * 页面初始化时注入批量控制面板。
         * 这里单独抽出来，便于后续如果要扩展更多批量工具时复用。
