         */
        addEagleButtonToActionGroup: function (btn_group, btn_share, status_id) {
            if (!btn_group || !btn_share || !status_id) return
            if (btn_group.querySelector(`.tmd-down-eagle[data-status-id="${status_id}"]`)) return

            const eagleBtn = btn_share.cloneNode(true)
            eagleBtn.dataset.statusId = status_id
            eagleBtn.classList.add('tmd-down-eagle')
            eagleBtn.title = lang.save_to_eagle

            const button = eagleBtn.querySelector('button')
            if (button) button.removeAttribute('disabled')
            const label = eagleBtn.querySelector('span')
            if (label) label.textContent = lang.save_to_eagle
            const svg = eagleBtn.querySelector('svg')
            if (svg) {
                svg.innerHTML = '<path d="M12 3v11m0 0l-4-4m4 4l4-4M4 17v1a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-1" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"></path>'
            }

            eagleBtn.onclick = async (event) => {
                event.preventDefault()
                event.stopPropagation()
                if (eagleBtn.classList.contains('loading')) return
                this.status(eagleBtn, 'loading', lang.save_to_eagle)
                try {
                    await this.eagle.checkAlive()
                    const payload = await this.prepareMediaPayload(status_id, { promptIfQuoted: true })
                    if (!payload || !payload.tasks || payload.tasks.length === 0) throw new Error('MEDIA_NOT_FOUND')
                    let savedCount = 0
                    let skippedCount = 0
                    for (const task of payload.tasks) {
                        const result = await this.eagle.addItemByUrl(task)
                        savedCount += Number(result?.savedCount || 0)
                        skippedCount += Number(result?.skippedCount || 0)
                        await this.sleep(150)
