                    this.status(
                        eagleBtn,
                        'completed',
                        savedCount > 0 ? lang.eagle_saved : (skippedCount > 0 ? lang.eagle_already_saved : lang.eagle_saved)
                    )
                } catch (err) {
                    this.status(eagleBtn, 'failed', err.message || String(err))
                }
            }

            const anchor = btn_share.nextSibling && btn_share.nextSibling.nextSibling ? btn_share.nextSibling.nextSibling : null
            btn_group.insertBefore(eagleBtn, anchor)
